BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels (id INTEGER PRIMARY KEY, name TEXT NOT NULL, url TEXT, tier TEXT, tag TEXT, blurb TEXT, featured TEXT, n INTEGER);
CREATE TABLE IF NOT EXISTS videos (id TEXT PRIMARY KEY, title TEXT NOT NULL, duration_s INTEGER, views INTEGER, channel_id INTEGER, category_id INTEGER);
CREATE TABLE IF NOT EXISTS tags (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS video_tags (video_id TEXT NOT NULL, tag_id INTEGER NOT NULL, PRIMARY KEY (video_id, tag_id));
